import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        # Check if it's a binary matrix (0/1)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        deg = [len(adj_list[i]) for i in range(n)]
    else:
        adj_list = adj
        deg = [len(adj_list[i]) for i in range(n)]

    # Trivial cases
    if n == 1:
        return [0]
    if all(d == 0 for d in deg):
        return [0] * n

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Initial upper bound from Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: (-deg[x], x))
    color_wp = greedy_color(order_wp)
    best_coloring = color_wp[:]
    best_k = num_colors(best_coloring)

    # If already optimal (lower bound from max clique size approximation via greedy)
    # We'll try to improve using DSATUR and RLF

    # DSATUR implementation
    def dsatur():
        color = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor sets for efficiency
        colored_neighbors = [set() for _ in range(n)]
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)

            if max_sat == -1:  # all uncolored, saturation 0
                # choose max degree in uncolored subgraph
                max_deg = -1
                for v in candidates:
                    d = sum(1 for u in adj_list[v] if u in uncolored)
                    if d > max_deg:
                        max_deg = d
                        best_v = v
                    elif d == max_deg:
                        if random.random() < 0.5:  # random tie-break
                            best_v = v
                v = best_v
            else:
                # tie-break by degree in uncolored subgraph
                max_deg = -1
                best_v = -1
                for v in candidates:
                    d = sum(1 for u in adj_list[v] if u in uncolored)
                    if d > max_deg:
                        max_deg = d
                        best_v = v
                    elif d == max_deg:
                        if random.random() < 0.5:
                            best_v = v
                v = best_v

            # Assign smallest available color
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c

            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if c not in colored_neighbors[u]:
                        colored_neighbors[u].add(c)
                        sat[u] += 1
            uncolored.remove(v)

        return color

    # Try DSATUR
    color_ds = dsatur()
    k_ds = num_colors(color_ds)
    if k_ds < best_k:
        best_k = k_ds
        best_coloring = color_ds[:]

    # RLF implementation
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        while uncolored:
            # Build maximal independent set for color c
            # Step 1: choose vertex with max degree in G[uncolored]
            max_deg = -1
            v1 = -1
            for v in uncolored:
                d = sum(1 for u in adj_list[v] if u in uncolored)
                if d > max_deg:
                    max_deg = d
                    v1 = v
            if v1 == -1:  # should not happen
                break
            S = [v1]
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == v1:
                    continue
                adjacent = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)

            # Step 2: while U not empty, select u with max |N(u) ∩ W|, tie-break by min degree in G[U]
            while U:
                best_u = -1
                max_score = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # score: number of neighbors in W
                    score = sum(1 for w in adj_list[u] if w in W)
                    # degree in G[U]
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if score > max_score:
                        max_score = score
                        min_deg_in_U = deg_u
                        best_u = u
                    elif score == max_score:
                        if deg_u < min_deg_in_U:
                            min_deg_in_U = deg_u
                            best_u = u
                        elif deg_u == min_deg_in_U:
                            if random.random() < 0.5:
                                best_u = u
                if best_u == -1:
                    break  # should not happen
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color c to all in S
            for v in S:
                color[v] = c
            # Remove S from uncolored (they are now colored)
            for v in S:
                uncolored.remove(v)
            # Next color
            c += 1

        return color

    # Try RLF
    color_rlf = rlf()
    k_rlf = num_colors(color_rlf)
    if k_rlf < best_k:
        best_k = k_rlf
        best_coloring = color_rlf[:]

    # Local search: Kempe chain to reduce color count
    def kempe_reduce(coloring):
        nonlocal best_k
        k = num_colors(coloring)
        # Try to eliminate color classes from highest downward
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            made_change = True
            while made_change and verts:
                made_change = False
                v = verts.pop()
                # Try to move v to a lower color directly
                for c in range(target_color):
                    conflict = False
                    for u in adj_list[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    # Rebuild verts list as some may have changed
                    verts = [v for v in range(n) if coloring[v] == target_color]
                    continue
                # Try Kempe chains
                for c in range(target_color):
                    # Check if v is in a Kempe chain of (target_color, c) that does not include any other vertex of target_color?
                    # We'll do BFS for the Kempe chain component containing v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    is_valid = True  # will become False if we see another target_color vertex
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        if coloring[node] == target_color and node != v:
                            is_valid = False  # another vertex of target_color in component
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    if is_valid:
                        # Swap colors in component: target_color <-> c
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        made_change = True
                        # Rebuild verts
                        verts = [v for v in range(n) if coloring[v] == target_color]
                        break
            # If after trying all vertices we still have target_color class, break and move to next lower target
            if any(coloring[v] == target_color for v in range(n)):
                # Could not eliminate this color class, try next lower
                continue
            else:
                # Successfully eliminated target_color, reduce k and restart from new top
                k = num_colors(coloring)
                # Reset target_color to new max
                target_color = k  # will be decreased by loop
        return coloring

    # Apply Kempe reduction to the best coloring so far
    improved = kempe_reduce(best_coloring[:])
    k_improved = num_colors(improved)
    if k_improved < best_k:
        best_k = k_improved
        best_coloring = improved[:]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = True
    if n == 0:
        return []
    if len(adj[0]) != n:
        is_matrix = False
    else:
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    if is_matrix:
        # Convert to adjacency list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        adj = adj_list
    else:
        # Ensure adjacency list is clean (no self-loops, duplicates)
        adj = [list(set(nei)) for nei in adj]
        for i in range(n):
            if i in adj[i]:
                adj[i].remove(i)
    # If no edges, all vertices can be color 0
    if all(len(nei) == 0 for nei in adj):
        return [0] * n

    # DSATUR implementation
    color = [-1] * n
    # saturation[v] = set of colors used by colored neighbors
    saturation = [set() for _ in range(n)]
    # degree in the uncolored subgraph (initially full degree)
    degree = [len(nei) for nei in adj]
    uncolored = set(range(n))

    # Helper: get mex of a set of colors
    def mex(s):
        c = 0
        while c in s:
            c += 1
        return c

    # Main loop
    while uncolored:
        # Select vertex with max saturation degree, tie-break by degree in uncolored subgraph, then random
        v = max(uncolored, key=lambda x: (len(saturation[x]), degree[x], random.random()))
        # Assign smallest available color
        c = mex(saturation[v])
        color[v] = c
        uncolored.remove(v)
        # Update saturation and degree for uncolored neighbors
        for u in adj[v]:
            if u in uncolored:
                saturation[u].add(c)
                degree[u] -= 1

    # Kempe chain refinement to reduce colors
    max_color = max(color) if n > 0 else -1
    # Try to reduce from max_color down to 1
    for target_color in range(max_color, 0, -1):
        # Vertices with target_color
        verts_target = [v for v in range(n) if color[v] == target_color]
        if not verts_target:
            continue
        # Try to recolor each vertex in verts_target to a lower color
        made_change = False
        for v in verts_target:
            # Try direct move to a lower color
            neighbor_colors = set(color[u] for u in adj[v])
            for c in range(target_color):
                if c not in neighbor_colors:
                    color[v] = c
                    made_change = True
                    break
            if made_change:
                break
            # Try Kempe chains for each lower color
            for c in range(target_color):
                if c in neighbor_colors:
                    continue  # direct move not possible, but maybe via Kempe
                # We attempt to swap colors c and target_color in the component of v
                # Build the Kempe chain component for colors {c, target_color} containing v
                stack = [v]
                visited = set()
                comp_target = set()  # vertices in component with color target_color
                comp_c = set()       # vertices in component with color c
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    col = color[node]
                    if col == target_color:
                        comp_target.add(node)
                    elif col == c:
                        comp_c.add(node)
                    else:
                        continue  # not part of the Kempe chain
                    for nb in adj[node]:
                        if nb not in visited and color[nb] in (c, target_color):
                            stack.append(nb)
                # Check if any neighbor of v has color c (should be true by earlier check)
                # After swap, vertices in comp_target become c, comp_c become target_color
                # We need to ensure that no vertex in comp_target gets a conflict when changed to c
                # Since the component is induced by colors c and target_color, and we are swapping,
                # the only potential conflict is if a vertex in comp_target has a neighbor outside
                # the component that is color c. But if such neighbor existed, it would be in the component.
                # Similarly for comp_c becoming target_color.
                # Therefore, the swap is always safe.
                # Perform swap: target_color -> c, c -> target_color in the component
                for node in comp_target:
                    color[node] = c
                for node in comp_c:
                    color[node] = target_color
                made_change = True
                break
            if made_change:
                break
        if not made_change:
            # Cannot eliminate this color class, break
            break
        # After potential change, rebuild verts_target and continue if any left
        verts_target = [v for v in range(n) if color[v] == target_color]
        if not verts_target:
            # Successfully eliminated target_color, continue to next lower
            continue
        else:
            # Still some vertices with target_color, cannot reduce further
            break

    return color

