def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    neighbors = [set(neigh) for neigh in graph]
    colors = [-1] * n
    saturation = [0] * n

    def mex(s):
        c = 0
        while c in s:
            c += 1
        return c

    for _ in range(n):
        max_sat = -1
        candidates = []
        for v in range(n):
            if colors[v] == -1:
                sat_v = saturation[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)
        if not candidates:
            break

        max_deg = -1
        final_candidates = []
        for v in candidates:
            deg_uncolored = sum(1 for u in neighbors[v] if colors[u] == -1)
            if deg_uncolored > max_deg:
                max_deg = deg_uncolored
                final_candidates = [v]
            elif deg_uncolored == max_deg:
                final_candidates.append(v)
        if not final_candidates:
            v = candidates[0]
        else:
            v = random.choice(final_candidates)

        forbidden = set()
        for u in neighbors[v]:
            if colors[u] != -1:
                forbidden.add(colors[u])
        c = mex(forbidden)
        colors[v] = c

        for u in neighbors[v]:
            if colors[u] == -1:
                has_c = False
                for w in neighbors[u]:
                    if colors[w] == c:
                        has_c = True
                        break
                if not has_c:
                    saturation[u] += 1

    max_color = max(colors) if n > 0 else -1
    changed = True
    while changed and max_color >= 0:
        changed = False
        for color in range(max_color, 0, -1):
            vertices_color = [v for v in range(n) if colors[v] == color]
            if not vertices_color:
                continue
            for v in vertices_color:
                for c in range(color):
                    conflict = False
                    for u in neighbors[v]:
                        if colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                break
        if changed:
            saturation = [0] * n
            for v in range(n):
                if colors[v] == -1:
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if colors[u] != -1:
                            neighbor_colors.add(colors[u])
                    saturation[v] = len(neighbor_colors)
            max_color = max(colors) if n > 0 else -1

    for v in range(n):
        if colors[v] == -1:
            forbidden = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    forbidden.add(colors[u])
            colors[v] = mex(forbidden)

    return colors

