def color_graph(adj: list[list[int]]) -> list[int]:
    # --- Input handling and adjacency normalization ---
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        # Quick check for binary entries (0/1) to confirm matrix
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list from input
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Already adjacency list; ensure it's a list of lists
        adj_list = [list(neighbors) for neighbors in adj]
    # Symmetrize adjacency list (undirected graph)
    for u in range(n):
        for v in adj_list[u]:
            if u not in adj_list[v]:
                adj_list[v].append(u)
    # Remove duplicate neighbors
    for i in range(n):
        adj_list[i] = list(set(adj_list[i]))
    # Precompute degrees
    degree = [len(adj_list[i]) for i in range(n)]
    # Handle trivial cases
    if n == 0:
        return []
    if n == 1:
        return [0]
    # Check for edgeless graph
    if all(d == 0 for d in degree):
        return [0] * n
    # Check for complete graph
    if all(d == n - 1 for d in degree):
        return list(range(n))
    # --- DSATUR with Kempe chain refinement ---
    # Initialize data structures
    color = [-1] * n
    saturation = [0] * n          # saturation degree (number of distinct colors in neighbors)
    neighbor_colors = [set() for _ in range(n)]  # colors present in neighbors
    uncolored = set(range(n))
    # Helper: compute mex (minimum excluded value)
    def mex(s):
        c = 0
        while c in s:
            c += 1
        return c
    # Helper: Kempe chain swap for colors a and b starting from vertex v
    def kempe_swap(v, a, b):
        if color[v] not in (a, b):
            return False
        stack = [v]
        visited = set()
        component = []
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if color[u] not in (a, b):
                continue
            component.append(u)
            for w in adj_list[u]:
                if color[w] in (a, b) and w not in visited:
                    stack.append(w)
        # Swap colors a and b in the component
        for u in component:
            if color[u] == a:
                color[u] = b
            elif color[u] == b:
                color[u] = a
        return True
    # Main DSATUR loop
    while uncolored:
        # Select vertex with max saturation degree, tie-break by degree in uncolored subgraph, then random
        v = -1
        max_sat = -1
        max_deg = -1
        for u in uncolored:
            sat_u = saturation[u]
            deg_u = 0
            for w in adj_list[u]:
                if w in uncolored:
                    deg_u += 1
            if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
               (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                max_sat = sat_u
                max_deg = deg_u
                v = u
        # Assign smallest available color
        c = mex(neighbor_colors[v])
        color[v] = c
        uncolored.remove(v)
        # Update saturation and neighbor colors for uncolored neighbors
        for w in adj_list[v]:
            if w in uncolored:
                if c not in neighbor_colors[w]:
                    neighbor_colors[w].add(c)
                    saturation[w] += 1
        # Kempe chain refinement: try to reduce color usage by eliminating the highest color class
        max_color = max(color) if color else -1
        if max_color > 0:
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, 0, -1):
                # Collect vertices with target_color
