                                    # This neighbor loses color target_color from its neighbor set
                                    if target_color in neighbor_colors[w]:
                                        neighbor_colors[w].remove(target_color)
                                        saturation[w] -= 1
                                if color[w] == c_low:
                                    # This neighbor gains color c_low (if not already present)
                                    if c_low not in neighbor_colors[w]:
                                        neighbor_colors[w].add(c_low)
                                        saturation[w] += 1
                            color[vtx] = c_low
