                    row.append(j)
            neighbors.append(row)
    else:
        # Input is adjacency list
        for i in range(n):
            # Ensure we have a list and filter out self-loops if any
            nbrs = [v for v in adj[i] if v != i and 0 <= v < n]
            neighbors.append(nbrs)

