    def greedy_color(order):
        color = [-1] * n
        used = [False] * n  # temporary for neighbor colors
        max_color = 0
        for v in order:
            # mark colors of colored neighbors
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            # find smallest free color
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            if c > max_color:
                max_color = c
            # unmark
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = False
        return max_color + 1, color

