            # select vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and degree[u] > max_deg) or \
                   (sat[u] == max_sat and degree[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat[u]
                    max_deg = degree[u]
                    v = u
