                        best_degU = degU
                        best_u = u
                if best_u == -1:
                    break  # U empty
                # add best_u to S
                S.add(best_u)
                inU[best_u] = False
                # move its neighbors from U to W
                for w in neighbors[best_u]:
                    if inU[w]:
                        inU[w] = False
                        inW[w] = True
            # assign color to all in S
            for v in S:
                color[v] = current_color
            # remove S from uncolored
            uncolored -= S
            current_color += 1
        return current_color, color

