    def degeneracy_ordering():
        # Compute degeneracy ordering (smallest-last)
        # We'll use bucket sort for efficiency
        degree = [len(neighbors[i]) for i in range(n)]
        max_deg = max(degree) if n > 0 else 0
        # buckets for degrees 0..max_deg
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            buckets[d].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        order = []  # removal order (smallest-last first)
        # current degree array (will be updated)
        curr_deg = degree[:]
        removed = [False] * n
        for _ in range(n):
            # find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            while removed[v]:
                if not buckets[ptr]:
                    break
                v = buckets[ptr].pop()
            if removed[v]:
                # find another
                found = False
                for d in range(ptr, max_deg+1):
                    while buckets[d]:
                        u = buckets[d].pop()
                        if not removed[u]:
                            v = u
                            found = True
                            break
                    if found:
                        break
                if not found:
                    # scan all
                    for u in range(n):
                        if not removed[u]:
                            v = u
                            break
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    # remove u from its current bucket
                    # we don't actually remove from bucket list, but we will skip removed ones
                    # instead, we decrement degree and add to appropriate bucket
                    curr_deg[u] -= 1
                    if curr_deg[u] < len(buckets):
                        buckets[curr_deg[u]].append(u)
                    else:
                        # should not happen if we manage bounds
                        pass
        # color in reverse order
        return greedy_color(order[::-1])

    # Helper: Welsh-Powell ordering
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Try multiple methods and pick the best (fewest colors)
    best_colors = n  # upper bound
    best_coloring = None

    # List of methods to try
    methods = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Degeneracy", degeneracy_ordering),
        ("Welsh-Powell", welsh_powell),
    ]

    for name, method in methods:
        try:
            num_colors, coloring = method()
            if num_colors < best_colors:
                best_colors = num_colors
                best_coloring = coloring
                # early exit if we hit lower bound: clique size or max degree +1? 
                # We can't easily compute clique, but if we hit 1 we can stop.
                if best_colors == 1:
