                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all vertices in S
            for vertex in S:
                color[vertex] = c
            # Remove S from uncolored
            uncolored -= S
            c += 1
        return color

