        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)
        pos = 0
        order = []
        curr_degree = degree[:]
        removed = [False] * n
        for _ in range(n):
            while pos <= max_deg and not buckets[pos]:
