    # Helper: RLF (Recursive Largest First) - builds maximal independent sets
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Start with vertex of maximum degree in the uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg = len([w for w in neighbors[u] if w in uncolored])
                if deg > max_deg:
                    max_deg = deg
                    v = u
                elif deg == max_deg and random.random() < 0.5:
                    v = u
            S = {v}  # independent set for color c
            U = uncolored - {v} - neighbors[v]  # vertices not adjacent to S (eligible)
            W = set(uncolored) - U - {v}        # vertices adjacent to S (ineligible for this color)
            while U:
                # Select u in U with max neighbors in W, break ties by min degree in U
                u_star = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    w_neighbors = len([w for w in neighbors[u] if w in W])
                    deg_U = len([w for w in neighbors[u] if w in U])
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_U = deg_U
                        u_star = u
                    elif w_neighbors == max_w_neighbors:
                        if deg_U < min_deg_U:
                            min_deg_U = deg_U
                            u_star = u
                        elif deg_U == min_deg_U and random.random() < 0.5:
                            u_star = u
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
