    def smallest_last():
        if n == 0:
            return []
        degree = [len(neighbors[i]) for i in range(n)]
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)
        pos = 0
        order = []
        curr_degree = degree[:]
        removed = [False] * n
        for _ in range(n):
            while pos <= max_deg and not buckets[pos]:
                pos += 1
            if pos > max_deg:
                break
            while buckets[pos] and removed[buckets[pos][-1]]:
                buckets[pos].pop()
            if not buckets[pos]:
                pos += 1
                continue
            v = buckets[pos].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d = curr_degree[u]
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    curr_degree[u] -= 1
                    d_new = curr_degree[u]
                    buckets[d_new].append(u)
                    if d_new < pos:
                        pos = d_new
