    # Helper: Kempe chain refinement to reduce color count
    def kempe_refine(coloring):
        color = coloring[:]
        n_local = n
        neighbors_local = neighbors
        improved = True
        while improved:
            improved = False
            max_color = max(color) if n_local > 0 else -1
            if max_color <= 0:
