                random.shuffle(verts)  # randomize to avoid bias
                for v in verts:
                    neighbor_colors = set(color[u] for u in neighbors_local[v])
                    # Try to recolor v to a lower color directly
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            color[v] = c
                            improved = True
