                    # Try Kempe chain swap for each lower color
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue
                        # Find the (target_color, c)-Kempe chain containing v
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if color[node] == target_color or color[node] == c:
                                component.add(node)
                                for nb in neighbors_local[node]:
                                    if color[nb] == target_color or color[nb] == c:
                                        if nb not in visited:
