            U = uncolored - {v} - neighbors[v]
            W = set(uncolored) - U - {v}
            while U:
                u_star = -1
                max_w_neighbors = -1
                min_index_u = float('inf')
                for u in U:
                    w_neighbors = len([w for w in neighbors[u] if w in W])
